// Bungkus teks panjang menjadi beberapa baris agar muat di lebar canvas tertentu; mengembalikan array baris yang sudah ditulis.
const wrapText = (ctx, text, x, y, maxWidth, lineHeight) => {
  const words = String(text || "").split(" ");
  let line = "";
  let curY = y;
  const written = [];
  words.forEach((word, idx) => {
    const testLine = line ? line + " " + word : word;
    if (ctx.measureText(testLine).width > maxWidth && line) {
      ctx.fillText(line, x, curY);
      written.push(line);
      line = word;
      curY += lineHeight;
    } else {
      line = testLine;
    }
    if (idx === words.length - 1) {
      ctx.fillText(line, x, curY);
      written.push(line);
    }
  });
  return written;
};

// Normalisasi nomor WA ke format internasional (kode negara Indonesia 62) untuk link wa.me.
// "0812..." -> "62812...", "812..." -> "62812...", "+62812..."/"62812..." dibiarkan apa adanya.
const toWhatsAppNumber = (v) => {
  let digits = (v || "").replace(/[^0-9]/g, "");
  if (digits.startsWith("0")) digits = "62" + digits.slice(1);
  else if (!digits.startsWith("62")) digits = "62" + digits;
  return digits;
};

