const buildStatusUpdateMessage = (order, shopInfo, status) => {
  const lines = [];
  lines.push(`🍢 *${shopInfo?.name || "Bakso Aci"}*`);
  lines.push(`Update Pesanan #${order.id.slice(0, 5).toUpperCase()} — No. Antrian ${String(order.queueNumber ?? "-").padStart(3, "0")}`);
  lines.push("");
  lines.push(`Status: *${status}*`);
  if (STATUS_MESSAGE[status]) lines.push(STATUS_MESSAGE[status]);
  lines.push("");
  lines.push(`Untuk: ${order.customer.name} (${order.customer.phone})`);
  return lines.join("\n");
};
const buildResiMessage = (order, shopInfo, paymentAccounts) => {
  const lines = [];
  lines.push(`🍢 *${shopInfo?.name || "Bakso Aci"}*`);
  lines.push(`No. Antrian: ${String(order.queueNumber ?? "-").padStart(3, "0")} · Order #${order.id.slice(0, 5).toUpperCase()}`);
  lines.push("—————————————");
  order.items.forEach((i) => lines.push(`${i.emoji} ${i.name} x${i.qty} = ${fmtRupiah(i.price * i.qty)}`));
  lines.push("—————————————");
  lines.push(`Subtotal: ${fmtRupiah(order.total)}`);
  if (EXPEDITION_BAYAR_DI_TEMPAT.includes(order.customer.expedition)) {
    lines.push(`Ongkos Kirim: Bayar langsung ke driver ${order.customer.expedition}`);
    lines.push(`*Total Bayar ke Toko: ${fmtRupiah(order.total)}*`);
  } else {
    lines.push(`Ongkos Kirim: ${fmtRupiah(order.ongkir || 0)}`);
    lines.push(`*Total Bayar: ${fmtRupiah(order.total + (order.ongkir || 0))}*`);
  }
  lines.push(`Metode Bayar: ${order.customer.payment || "-"}`);
  if (order.customer.payment && paymentAccounts?.[order.customer.payment]) {
    lines.push(`No. ${order.customer.payment}: ${paymentAccounts[order.customer.payment]}`);
  }
  lines.push("");
  lines.push(`👤 ${order.customer.name}`);
  lines.push(`📱 ${order.customer.phone}`);
  lines.push(`📍 ${order.customer.address}`);
  lines.push("");
  lines.push("Terima kasih sudah pesan! 🙏 Pesanan akan segera diproses.");
  return lines.join("\n");
};

